        }
        
        // Execute the main batch AMB functionality
        executeBatchAMBFunction();
        
        // Reset appearance
        setTimeout(() => {
            widget.style.transform = 'scale(1)';
            widget.style.background = '';
            
            if (statusElement) {
                statusElement.textContent = 'Click to run';
                statusElement.style.color = '#2c3e50';
            }
        }, 2000);
    }
    
    function executeBatchAMBFunction() {
