// Configuration
const BATCH_WIDGET_CONFIG = {
    refreshInterval: 60000, // 60 seconds
    autoMinimizeDelay: 45000, // 45 seconds
    widgetWidth: 500,
    plantColors: {
        '1': '#3498db', // Mix Plant - Blue
        '2': '#e74c3c', // Dry Plant - Red
        '3': '#2ecc71', // Juice Plant - Green
        '4': '#f39c12', // Laboratory - Orange
