    },
    companyColors: {
        'AMB-Wellness': '#1abc9c',
        'Juice': '#3498db'
    }
};

// Initialize when page loads
frappe.ready(function() {
    // Initialize widget only for logged-in users
    if (frappe.session.user !== 'Guest') {
        console.log('Initializing Enhanced Batch Navbar Widget...');

        // Set up auto-refresh
        setInterval(function() {
            update_batch_announcements();
        }, BATCH_WIDGET_CONFIG.refreshInterval);

        // Initial load after 2 seconds
        setTimeout(function() {
            update_batch_announcements();
        }, 2000);
    }
});

// =============================================================================
// MAIN FUNCTIONS
// =============================================================================

function update_batch_announcements() {
    frappe.call({
        method: 'erpnext.manufacturing.doctype.batch_amb.batch_amb.get_enhanced_running_batch_announcements',
        callback: function(r) {
            if (r.message && r.message.success) {
                if (r.message.grouped_announcements && Object.keys(r.message.grouped_announcements).length > 0) {
                    display_grouped_batch_announcements(r.message.grouped_announcements);
                } else if (r.message.flat_announcements && r.message.flat_announcements.length > 0) {
                    // Fallback to flat announcements
                    display_batch_announcements(r.message.flat_announcements);
                } else {
                    // Hide widget if no running batches
                    $('.batch-announcement-widget').fadeOut();
                }
            } else {
                console.log('No running batches or API error');
                $('.batch-announcement-widget').fadeOut();
            }
        },
        error: function(r) {
            console.error('Error fetching batch announcements:', r);
        }
    });
}

function display_grouped_batch_announcements(groupedData) {
    let announcement_html = '';
    let totalBatches = 0;
    
    // Process by company
    for (const [companyName, companyData] of Object.entries(groupedData)) {
        const companyColor = BATCH_WIDGET_CONFIG.companyColors[companyName] || '#7f8c8d';
        let companyBatches = 0;
        
        announcement_html += `
            <div class="company-group" style="margin-bottom: 15px;">
                <div class="company-header" style="
                    display: flex; 
                    align-items: center; 
                    padding: 8px 12px;
                    background: ${companyColor};
                    color: white;
                    border-radius: 5px;
                    margin-bottom: 10px;
                    font-weight: bold;
                ">
                    <span style="margin-right: 8px;">🏢</span>
                    ${companyName}
                </div>
        `;
        
        // Process by plant
        for (const [plantCode, plantBatches] of Object.entries(companyData)) {
            const plantColor = BATCH_WIDGET_CONFIG.plantColors[plantCode] || '#95a5a6';
            const plantName = getPlantName(plantCode);
            
            announcement_html += `
                <div class="plant-group" style="margin-left: 10px; margin-bottom: 12px;">
                    <div class="plant-header" style="
                        display: flex; 
                        align-items: center; 
                        padding: 6px 10px;
                        background: ${plantColor}22;
                        border-left: 4px solid ${plantColor};
                        border-radius: 3px;
                        margin-bottom: 8px;
                        font-size: 13px;
                    ">
