                        ${plantName} (Plant ${plantCode})
                    </div>
                    <div class="batch-list">
            `;
            
            // Process batches
            plantBatches.forEach(function(batch, index) {
                companyBatches++;
                totalBatches++;
                
                const priorityColor = batch.priority === 'high' ? '#00ff00' : 
                                    batch.priority === 'medium' ? '#ffff00' : '#ff9900';
                const statusIcon = getStatusIcon(batch.batch_status);
                
                announcement_html += `
                    <div class="batch-announcement-item" style="
                        margin-bottom: 10px; 
                        padding: 10px; 
                        background: #f8f9fa; 
                        border-radius: 5px;
                        border-left: 4px solid ${priorityColor};
                        font-family: 'Courier New', monospace;
                        position: relative;
                    ">
                        <div style="display: flex; justify-content: space-between; align-items: flex-start;">
                            <div style="flex: 1;">
                                <div style="font-weight: bold; margin-bottom: 5px; font-size: 13px; color: #2c3e50;">
                                    ${statusIcon} ${batch.title}
                                </div>
                                <div style="font-size: 11px; color: #34495e; margin-bottom: 5px;">
                                    ${batch.content.replace(/\n/g, '<br>')}
                                </div>
                            </div>
                            <div style="
                                background: rgba(0,0,0,0.05);
                                padding: 3px 6px;
                                border-radius: 3px;
                                font-size: 9px;
                                white-space: nowrap;
                                margin-left: 8px;
                                color: ${batch.quality_grade === 'Red' ? '#e74c3c' : 
                                       batch.quality_grade === 'Yellow' ? '#f39c12' : '#2ecc71'};
                            ">
                                ${batch.quality_grade || 'N/A'}
                            </div>
                        </div>
                        <div style="
                            position: absolute;
                            top: 8px;
                            right: 8px;
                            background: rgba(0,0,0,0.1);
                            padding: 2px 6px;
                            border-radius: 3px;
                            font-size: 9px;
                        ">
                            ${formatTime(batch.timestamp)}
                        </div>
                    </div>
                `;
            });
            
            announcement_html += `
                    </div>
                </div>
            `;
        }
        
        // Add company batch count
        announcement_html = announcement_html.replace('${companyName}', `${companyName} (${companyBatches})`);
        
        announcement_html += `</div>`;
    }
    
    if (announcement_html) {
        show_navbar_widget(announcement_html, totalBatches);
    }
}

function display_batch_announcements(announcements) {
    // Fallback to original display for backward compatibility
    let announcement_html = '';
    
    announcements.forEach(function(announcement, index) {
        let priorityColor = announcement.priority === 'high' ? '#00ff00' : '#ffff00';
        
