                    transform: translateX(100%);
                    opacity: 0;
                }
                to {
                    transform: translateX(0);
                    opacity: 1;
                }
            }

            .batch-announcement-widget {
                transition: all 0.3s ease;
            }

            .batch-announcement-item {
                transition: all 0.2s ease;
            }

            .batch-announcement-item:hover {
                transform: translateX(-3px);
                box-shadow: 0 3px 10px rgba(0,0,0,0.2);
            }

            .company-group {
                transition: all 0.3s ease;
            }

            .plant-group {
                transition: all 0.3s ease;
            }

            @media (max-width: 768px) {
                .batch-announcement-widget {
                    width: calc(100vw - 40px) !important;
                    right: 20px !important;
                    font-size: 12px !important;
                }
            }

            /* Scrollbar styling */
            .batch-announcement-widget::-webkit-scrollbar {
                width: 6px;
            }
            
            .batch-announcement-widget::-webkit-scrollbar-track {
                background: #f1f1f1;
                border-radius: 10px;
            }
            
            .batch-announcement-widget::-webkit-scrollbar-thumb {
                background: #888;
                border-radius: 10px;
            }
            
            .batch-announcement-widget::-webkit-scrollbar-thumb:hover {
                background: #555;
            }
        </style>
    `);
}

