function setup_history_table(frm) {
    // Make history table read-only and properly formatted
    frm.fields_dict.processing_history.grid.set_column_disp("batch_reference", false);
    
    // Set column widths for better display
    frm.fields_dict.processing_history.grid.update_docfield_property(
        "date", "width", 120
    );
    frm.fields_dict.processing_history.grid.update_docfield_property(
        "plant", "width", 80
    );
    frm.fields_dict.processing_history.grid.update_docfield_property(
        "processing_action", "width", 150
    );
}

function refresh_history_table(frm) {
    // Sort history by date descending (newest first)
    if (frm.doc.processing_history) {
        frm.doc.processing_history.sort(function(a, b) {
            return new Date(b.date) - new Date(a.date);
        });
        frm.refresh_field('processing_history');
    }
}

function add_history_action_buttons(frm) {
    // Add button to view full history
    if (!frm.is_new() && frm.doc.processing_history && frm.doc.processing_history.length > 0) {
        frm.add_custom_button(__('View Full History'), function() {
            show_full_history_report(frm);
        }, __('Tools'));
    }
}

function show_full_history_report(frm) {
    // Open a dialog with the complete processing history
    var dialog = new frappe.ui.Dialog({
        title: __('Complete Processing History - ' + frm.doc.name),
        fields: [
            {
                fieldname: 'history_html',
                fieldtype: 'HTML'
            }
        ],
        size: 'large'
    });
    
    // Generate HTML table for history
    var html = `<div style="max-height: 400px; overflow-y: auto;">
        <table class="table table-bordered">
            <thead>
                <tr>
                    <th>Date</th>
                    <th>Plant</th>
                    <th>Action</th>
                    <th>Item Code</th>
                    <th>Quality</th>
                    <th>Changed By</th>
                    <th>Comments</th>
                </tr>
            </thead>
            <tbody>`;
    
    frm.doc.processing_history.forEach(function(entry) {
        html += `<tr>
            <td>${frappe.datetime.str_to_user(entry.date)}</td>
            <td>${entry.plant}</td>
            <td>${entry.processing_action}</td>
            <td>${entry.item_code}</td>
            <td>${entry.quality_status}</td>
            <td>${entry.changed_by}</td>
            <td>${entry.comments || ''}</td>
        </tr>`;
    });
    
    html += `</tbody></table></div>`;
    
    dialog.fields_dict.history_html.$wrapper.html(html);
    dialog.show();
}

// Add to your existing utility functions
function add_manual_history_entry(frm, action, comments) {
    // Allow users to add manual history entries
    frappe.prompt([
        {
            fieldname: 'comments',
            label: __('Comments'),
            fieldtype: 'Text',
            reqd: 1,
            default: comments
        }
    ], function(values) {
        frappe.call({
            method: 'your_app.your_module.doctype.batch_amb.batch_amb.add_manual_history_entry',
            args: {
                batch_name: frm.doc.name,
                action: action,
                comments: values.comments,
                user: frappe.session.user
            },
            callback: function(r) {
                if (r.message) {
                    frm.reload_doc();
                    frappe.msgprint(__('History entry added successfully'));
                }
            }
        });
    }, __('Add History Entry'), __('Add'));
}

// Override Work Order list to show drafts
if (frappe.views.ListView) {
    const original_setup = frappe.views.ListView.prototype.setup_defaults;
    frappe.views.ListView.prototype.setup_defaults = function() {
        original_setup.call(this);
        if (this.doctype === 'Work Order') {
            // Include drafts in the query
            this.filters = this.filters || [];
            // Remove any existing docstatus filter
            this.filters = this.filters.filter(f => f[1] !== 'docstatus');
        }
    };
}

frappe.listview_settings['Work Order'] = {
    add_fields: ['status', 'docstatus', 'production_item', 'qty'],
    get_indicator: function(doc) {
        if (doc.docstatus === 0) {
            return [__('Draft'), 'red', 'docstatus,=,0'];
        } else if (doc.status === 'Not Started') {
            return [__('Not Started'), 'orange', 'status,=,Not Started'];
        } else if (doc.status === 'In Process') {
            return [__('In Process'), 'blue', 'status,=,In Process'];
        } else if (doc.status === 'Completed') {
            return [__('Completed'), 'green', 'status,=,Completed'];
        } else if (doc.status === 'Stopped') {
            return [__('Stopped'), 'red', 'status,=,Stopped'];
        }
    }
};
